d() { kubectl --context main -n web-portal get deploy portal -o jsonpath="$1" 2>/dev/null; }
check "portal runs the 'enable gzip' version (nginx:1.28-alpine, FEATURE_GZIP=on, no FEATURE_CACHE)" bash -c "[ \"\$(kubectl --context main -n web-portal get deploy portal -o jsonpath='{.spec.template.spec.containers[0].image} {.spec.template.spec.containers[0].env[*].name}={.spec.template.spec.containers[0].env[*].value}')\" = 'nginx:1.28-alpine FEATURE_GZIP=on' ]"
check "portal is fully rolled out" bash -c "[ \"\$(kubectl --context main -n web-portal get deploy portal -o jsonpath='{.status.updatedReplicas}/{.status.readyReplicas}/{.status.replicas}')\" = \"\$(kubectl --context main -n web-portal get deploy portal -o jsonpath='{.status.replicas}/{.status.replicas}/{.status.replicas}')\" ] && [ -z \"\$(kubectl --context main -n web-portal get deploy portal -o jsonpath='{.status.unavailableReplicas}')\" ]"
check "container nginx requests cpu 100m, memory 64Mi and limits cpu 200m" bash -c "[ \"\$(kubectl --context main -n web-portal get deploy portal -o jsonpath='{.spec.template.spec.containers[0].resources.requests.cpu} {.spec.template.spec.containers[0].resources.requests.memory} {.spec.template.spec.containers[0].resources.limits.cpu}')\" = '100m 64Mi 200m' ]"
check "HPA portal (autoscaling/v2): 2–6 replicas, 60% CPU, scale-down window 120s" bash -c "[ \"\$(kubectl --context main -n web-portal get hpa.v2.autoscaling portal -o jsonpath='{.spec.scaleTargetRef.kind}/{.spec.scaleTargetRef.name} {.spec.minReplicas} {.spec.maxReplicas} {.spec.metrics[0].resource.name} {.spec.metrics[0].resource.target.type} {.spec.metrics[0].resource.target.averageUtilization} {.spec.behavior.scaleDown.stabilizationWindowSeconds}')\" = 'Deployment/portal 2 6 cpu Utilization 60 120' ]"
check "HPA portal is actively scaling (gets CPU metrics)" bash -c "[ \"\$(kubectl --context main -n web-portal get hpa portal -o jsonpath='{.status.conditions[?(@.type==\"ScalingActive\")].status}')\" = True ]"
